using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;
namespace GearLab {public static class Reference67Tests {
 public static int Native(string folder){Directory.CreateDirectory(folder);try{var d=ReferenceRobot67.Cached();var source=d.Joints[1];var changes=new List<object>();using(var kernel=new CADKernel())foreach(string name in new[]{"length","wall","motor"}){File.WriteAllText(Path.Combine(folder,"reference67-native-progress.txt"),name);var copy=d.Clone();var joint=copy.Joints[1];if(name=="length")joint.EndZ+=20;if(name=="wall")joint.BodyGenerator.FrameWall+=.4;if(name=="motor")joint.MotorLength+=2;var before=source.GeneratedBody.Result;var result=ProceduralBodySpec.Generate(kernel,copy,joint,joint.BodyGenerator);if(!result.Result.GeometryValid||result.Fingerprint==source.GeneratedBody.Fingerprint)throw new Exception("Native regeneration: "+name);double oldVolume=before.Parts.Where(p=>p.Role=="frame"||p.Role=="mount").Sum(p=>p.Volume),newVolume=result.Result.Parts.Where(p=>p.Role=="frame"||p.Role=="mount").Sum(p=>p.Volume);if(Math.Abs(newVolume-oldVolume)<1)throw new Exception("No physical CAD change: "+name);if(name=="length"){var a=before.Mates.First(m=>m.Id=="link_child").Origin;var c=result.Result.Mates.First(m=>m.Id=="link_child").Origin;if(Math.Sqrt(a.Zip(c,(x,y)=>(x-y)*(x-y)).Sum())<19.9)throw new Exception("Flange did not move");}changes.Add(new{Name=name,BeforeVolume=oldVolume,AfterVolume=newVolume,GeometryValid=result.Result.GeometryValid});}File.WriteAllText(Path.Combine(folder,"reference67-native-results.json"),CADDocument.Serializer().Serialize(new{Passed=true,Changes=changes}),Encoding.UTF8);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"reference67-native-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 public static int Run(string folder){Directory.CreateDirectory(folder);int checks=0;var log=new StringBuilder();Action<bool,string> check=(v,m)=>{if(!v)throw new Exception(m);checks++;log.AppendLine("PASS "+m);};try{
 var d=ReferenceRobot67.Cached();check(d.Validate().Count==0,"editable reference layout validates");check(d.Joints.Count==6&&d.Joints.All(j=>j.BodyGenerator.Variant=="Reference67"&&!j.BodyGenerator.BlenderDesign),"six independent CAD axes");check(d.Joints.Last().Payload==.3,"300 g is a payload requirement");check(d.Joints.All(j=>j.MotorTorque==0),"unknown working motor torque remains unknown");
 foreach(var j in d.Joints){check(j.GeneratedBody!=null&&j.GeneratedBody.Result.GeometryValid,"native CAD solids valid "+j.Id);check(j.GeneratedBody.Fingerprint==ProceduralBodySpec.Fingerprint(d,j,j.BodyGenerator),"current cache "+j.Id);check(j.GeneratedBody.Result.Mates.All(m=>m.BoresVerified),"real mating bores "+j.Id);check(!j.GeneratedBody.Result.ReadyForManufacture,"manufacturing approval remains false "+j.Id);check(j.GeneratedBody.Result.Parts.All(p=>!string.IsNullOrEmpty(p.Step)),"embedded independent STEP parts "+j.Id);}
 var b=RobotCad.Build(d);check(b.Model.Valid,"assembly builds");check(RobotConnections.Validate(b).Count==0,"all world mounting frames coincide");check(b.Entries.Values.Count(e=>e.Part.BearingSource!=null&&e.Part.BearingElement==1&&!e.InputSide)>=12,"two detailed bearing supports per axis");check(b.Entries.Values.Count(e=>e.BearingGain>0&&e.BearingGain<.5)>12,"rolling elements and cages move relative to rings");check(d.Joints[2].GeneratedBody.Result.Parts.Count(p=>p.Role=="motor")==3,"three wrist NEMA17 envelopes in forearm");check(b.Entries.Values.Where(e=>e.Category=="Мотор").All(e=>!e.Printable),"motors excluded from printable parts");
 var random=new Random(67);for(int n=0;n<24;n++){foreach(var j in d.Joints)j.Position=j.Minimum+(j.Maximum-j.Minimum)*random.NextDouble();b.InvalidatePose();check(RobotConnections.Validate(b).Count==0,"kinematic mates in pose "+n);}d=ReferenceRobot67.Cached();
 var source=d.Joints[1];string fp=ProceduralBodySpec.Fingerprint(d,source,source.BodyGenerator);foreach(string name in new[]{"FrameWall","SkinWall","Clearance","Density"}){var c=d.Clone();var j=c.Joints[1];var p=typeof(ProceduralBodySettings).GetProperty(name);p.SetValue(j.BodyGenerator,(double)p.GetValue(j.BodyGenerator,null)+.1,null);check(ProceduralBodySpec.Fingerprint(c,j,j.BodyGenerator)!=fp,"cache invalidated by "+name);}
 var changed=d.Clone();changed.Joints[1].EndZ+=20;bool blocked=false;try{RobotCad.Build(changed).ForExport(true,null);}catch{blocked=true;}check(blocked,"stale native CAD cannot be exported after dimension edit");
 foreach(string name in new[]{"Robot1_800mm","SixAxis_Connected","Industrial_1000mm"}){string root=Path.GetDirectoryName(System.Windows.Forms.Application.ExecutablePath);string path=Path.Combine(root,"examples",name+".robot.json");if(!File.Exists(path))path=Path.Combine(Path.GetDirectoryName(root),"examples",name+".robot.json");var old=RobotDocument.Parse(File.ReadAllText(path));foreach(var j in old.Joints)check(j.GeneratedBody.Fingerprint==ProceduralBodySpec.Fingerprint(old,j,j.BodyGenerator),"legacy CAD cache "+name+" / "+j.Id);}
 var sizes=d.Joints.SelectMany(j=>j.GeneratedBody.Result.Parts.Where(p=>p.Role!="metal"&&p.Role!="hardware"&&p.Role!="insert"&&p.Role!="motor"&&p.Role!="guide").Select(p=>new{Joint=j.Id,p.Id,Size=new[]{p.Bounds[3]-p.Bounds[0],p.Bounds[4]-p.Bounds[1],p.Bounds[5]-p.Bounds[2]}})).ToArray();
 File.WriteAllText(Path.Combine(folder,"reference67-layout-results.json"),CADDocument.Serializer().Serialize(new{ManufacturingReady=false,PayloadRequirementKg=.3,MotorTorqueKnown=false,FullRangeCollisionChecked=false,NominalHeightParameter=1000,MassKg=d.Joints.Sum(j=>j.GeneratedBody.Result.MassKg)+3*.29,Parts=sizes}),Encoding.UTF8);
 File.WriteAllText(Path.Combine(folder,"reference67-results.txt"),log+"PASS "+checks+" assertions",Encoding.UTF8);return 0;
 }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"reference67-error.txt"),log+ex.ToString(),Encoding.UTF8);return 1;}}
}}
